import { accountRouter, defineApp, defineProvider, oauth2, object, secrets, string, withApprovals } from "apps";
import { always } from "apps/operations/approval";
import { mcpHealth, mcpRouter } from "apps/mcp";

const gitlab = defineProvider({
  name: "GitLab MCP",
  hosts: ["gitlab.com"],
  site: { label: "GitLab instance URL", origin: "https://gitlab.com", defaultOrigin: true },
  auth: {
    oauth: oauth2({
      authorizationUrl: "https://gitlab.com/oauth/authorize",
      tokenUrl: "https://gitlab.com/oauth/token",
      revocationUrl: "https://gitlab.com/oauth/revoke",
      tokenEndpointAuthMethod: "client_secret_post",
      scopes: ["mcp"],
    }),
    token: secrets({
      label: "Fine-grained personal access token",
      fields: object({ token: string({ minLength: 1 }) }),
    }),
  },
  health: (check) => mcpHealth(check, {
    url: new URL("/api/v4/mcp", check.account.site ?? "https://gitlab.com").href,
    headers: { Authorization: `Bearer ${check.account.method === "oauth" ? check.account.fields.access_token : check.account.fields.token}` },
  }),
});

export default defineApp(
  { user: { accounts: { gitlab: gitlab.many() } } },
  async ({ user, cache, signal }) => ({
    tools: await accountRouter(
      user?.accounts.gitlab ?? [],
      async (account) => withApprovals(await mcpRouter({
        url: new URL("/api/v4/mcp", account.site ?? "https://gitlab.com").href,
        headers: { Authorization: `Bearer ${account.method === "oauth" ? account.fields.access_token : account.fields.token}` },
        account, cache, signal,
      }), () => always()),
      { signal },
    ),
  }),
);
